    for _ in range(N):
        x = int(next(iterator))
        y = int(next(iterator))
        bales.append((x, y))

    bale_set = set(bales)

    # Directions: North, South, East, West
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    perimeter = 0

    for x, y in bales:
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if (nx, ny) not in bale_set:
                perimeter += 1

    print(perimeter)

